<?php
declare(strict_types=1);require __DIR__.'/test_client.php';
function approve_and_execute(string $id,string $reviewer):void{$r=row('SELECT * FROM rs_requests WHERE id=?',[$id]);ok_api('request-decision',['id'=>$id,'version'=>$r['version'],'proposal_hash'=>$r['proposal_hash'],'decision'=>'approved','reason'=>'Independent local fixture review'],$reviewer);ok_api('request-execute',['id'=>$id,'version'=>(int)$r['version']+1,'proposal_hash'=>$r['proposal_hash'],'evidence'=>'Local integration evidence; no real payment or legal process'],$reviewer);}
try{
 // Reset only the isolated fixture server's public-intake test buckets between regression runs.
 foreach(['signup:127.0.0.1','recovery:127.0.0.1','intake-access:127.0.0.1'] as $scope)sql('DELETE FROM rs_rate_limits WHERE bucket=?',[hash('sha256',$scope)]);
 $customer=login_fixture('customer');$other=login_fixture('customer_secondary');$driver=login_fixture('driver');$admin=login_fixture('admin');$reviewer=login_fixture('admin_reviewer');$onboarding=login_fixture('onboarding');$support=login_fixture('support');$compliance=login_fixture('compliance');$privacyReviewer=login_fixture('compliance_reviewer');
 $boot=ok_api('bootstrap',null,$customer);$product=array_values(array_filter($boot['products'],fn($p)=>$p['product_key']==='car'))[0];$places=$boot['places'];
 $quote=ok_api('quote',['pickup'=>$places[0],'destination'=>$places[1],'product_id'=>$product['id'],'needs'=>['passengers'=>1]],$customer)['quote'];
 check(str_starts_with($quote['route_source'],'gh11.1-')&&count(decode($quote['route_json']))>2&&(int)$quote['duration_seconds']>0,'Quote uses actual self-hosted road geometry and duration');
 ok_api('driver-availability',['online'=>true],$driver);
 [$s]=call_api('driver-heartbeat',['lat'=>$places[0]['lat'],'lng'=>$places[0]['lng'],'accuracy'=>10,'observed_at'=>time()-300],$driver);check($s===422,'Stale GPS cannot be relabeled as fresh');
 [$s]=call_api('document-upload',['kind'=>'license','vehicle_id'=>1,'expires_at'=>'2027-02-31','data'=>'invalid'],$driver);check($s===422,'Invalid document expiry is rejected');
 $png='iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mP8/x8AAwMCAO+aD1sAAAAASUVORK5CYII=';
 $upload=ok_api('document-upload',['kind'=>'identity','data'=>$png],$driver);$document=(int)$upload['document_id'];check(row('SELECT scan_status FROM rs_documents WHERE id=?',[$document])['scan_status']==='clean','Private upload passes actual local malware scanning');
 [$s]=call_api('document-data',null,$customer,['id'=>$document]);check($s===403,'Customer cannot download driver identity evidence');
 [$s]=call_api('document-data',null,$support,['id'=>$document]);check($s===403,'Ordinary support cannot download onboarding evidence');
 $file=ok_api('document-data',null,$onboarding,['id'=>$document]);check(hash_equals($file['data'],$png),'Permitted reviewer receives the encrypted file after authenticated decryption');
 $case=ok_api('create-case',['category'=>'other','subject'=>'Private attachment fixture','message'=>'Local evidence verification'],$customer)['case_id'];$cv=ok_api('case',null,$customer,['id'=>$case])['case'];$attachment=ok_api('case-attachment',['id'=>$case,'version'=>$cv['version'],'data'=>$png],$customer)['attachment_id'];
 check(ok_api('attachment-data',null,$customer,['id'=>$attachment])['data']===$png,'Owner can read a scanned case attachment');[$s]=call_api('attachment-data',null,$other,['id'=>$attachment]);check($s===403,'Other customers cannot read case attachments');
 $phone='+88019'.random_int(10000000,99999999);$password='Fixture!'.bin2hex(random_bytes(10));$terms=ok_api('public-terms')['terms'][0];
 [$s]=call_api('signup',['name'=>'Test extended account','phone'=>$phone,'password'=>$password,'accept_terms'=>true,'terms_id'=>0]);check($s===409,'Signup rejects consent to an outdated or unreviewed terms version');
 ok_api('signup',['name'=>'Test extended account','phone'=>$phone,'password'=>$password,'accept_terms'=>true,'terms_id'=>$terms['id']]);$token=ok_api('login',['phone'=>$phone,'password'=>$password,'client'=>'android'])['token'];$user=ok_api('bootstrap',null,$token)['user'];
 ok_api('driver-apply',['product_id'=>$product['id'],'vehicle'=>'Test application vehicle','plate'=>'TEST-EXT-'.random_int(1000,9999),'capacity'=>4,'equipment'=>['luggage'=>true]],$token);$applicant=ok_api('bootstrap',null,$token)['user'];check(in_array('driver_application',$applicant['permissions'])&&!in_array('driver',$applicant['permissions']),'Enrollment grants applicant access without operative driver privileges');
 [$s]=call_api('driver-availability',['online'=>true],$token);check($s===403,'Applicant cannot go online through the endpoint');
 $intake=ok_api('recovery-intake',['kind'=>'recovery','contact'=>$phone,'message'=>'Local recovery fixture']);$status=ok_api('restricted-status',['reference'=>$intake['reference'],'access_key'=>$intake['access_key']]);check($status['status']==='pending'&&!$status['recovery_available'],'Restricted intake does not restore ordinary account privileges');
 [$s]=call_api('restricted-status',['reference'=>$intake['reference'],'access_key'=>str_repeat('0',64)]);check($s===422,'Intake status requires its private access key');
 ok_api('intake-update',['id'=>$intake['reference'],'version'=>1,'status'=>'verified','reason'=>'Manually checked isolated fixture identity and matched contact evidence','reply'=>'Identity checked for the local fixture.'],$admin);
 $request=ok_api('create-request',['kind'=>'recovery','reason'=>'Verified local intake','payload'=>['user_id'=>$user['id'],'intake_id'=>$intake['reference'],'identity_evidence'=>'Independent fixture identity match']],$admin)['request_id'];$r=row('SELECT * FROM rs_requests WHERE id=?',[$request]);
 [$s]=call_api('request-decision',['id'=>$request,'version'=>1,'proposal_hash'=>$r['proposal_hash'],'decision'=>'approved','reason'=>'Self approval'],$admin);check($s===403,'Recovery requester cannot approve their own proposal');approve_and_execute($request,$reviewer);
 $new='Recovered!'.bin2hex(random_bytes(10));ok_api('restricted-reset',['reference'=>$intake['reference'],'access_key'=>$intake['access_key'],'new_password'=>$new]);[$s]=call_api('bootstrap',null,$token);check($s===401,'Approved recovery revokes all previous sessions');
 [$s]=call_api('restricted-reset',['reference'=>$intake['reference'],'access_key'=>$intake['access_key'],'new_password'=>$new]);check($s===409,'Recovery grant cannot be reused');$token=ok_api('login',['phone'=>$phone,'password'=>$new,'client'=>'android'])['token'];
 $hold=ok_api('create-request',['kind'=>'legal_hold','reason'=>'Local hold fixture only','payload'=>['user_id'=>$user['id'],'legal_reason'=>'Fixture preservation scope','legal_basis'=>'Test only, no real legal claim','jurisdiction'=>'Local fixture','expires_at'=>gmdate('Y-m-d',time()+86400*30)]],$compliance)['request_id'];approve_and_execute($hold,$privacyReviewer);
 $deletion=ok_api('create-request',['kind'=>'account_deletion','reason'=>'Local erasure fixture','password'=>$new,'payload'=>[]],$token)['request_id'];$r=row('SELECT * FROM rs_requests WHERE id=?',[$deletion]);ok_api('request-decision',['id'=>$deletion,'version'=>1,'proposal_hash'=>$r['proposal_hash'],'decision'=>'approved','reason'=>'Identity verified'],$compliance);[$s]=call_api('request-execute',['id'=>$deletion,'version'=>2,'proposal_hash'=>$r['proposal_hash'],'evidence'=>'Fixture only'],$compliance);check($s===409,'Legal hold prevents account erasure');
 $release=ok_api('create-request',['kind'=>'legal_hold','reason'=>'Release local fixture hold','payload'=>['user_id'=>$user['id'],'release_id'=>$hold]],$compliance)['request_id'];approve_and_execute($release,$privacyReviewer);ok_api('request-execute',['id'=>$deletion,'version'=>2,'proposal_hash'=>$r['proposal_hash'],'evidence'=>'Fixture hold released and identity rechecked'],$compliance);check(row('SELECT phone,status FROM rs_users WHERE id=?',[$user['id']])['status']==='deleted','Erasure pseudonymizes contact after permitted hold release');
 check((int)sql('SELECT COUNT(*) FROM rs_users WHERE totp_secret IS NOT NULL AND totp_secret NOT LIKE "enc:%"')->fetchColumn()===0,'Staff MFA secrets are encrypted at rest');
 ok_api('driver-availability',['online'=>false],$driver);
 file_put_contents(__DIR__.'/../.local/backend/extended-verification.json',j(['passed'=>$checks,'time'=>gmdate('c'),'database'=>'rideshare_connected','scanner'=>'ClamAV 1.5.4 offline daemon','routing'=>'GraphHopper 11.1']));echo "Verified {$checks} extended workflow checks.\n";
}catch(Throwable $e){fwrite(STDERR,$e->getMessage()."\n");exit(1);}
